package io.mateu.workflow;

import static org.assertj.core.api.Assertions.assertThatCode;

import io.mateu.workflow.rules.grpc.GetRuleRequest;
import org.junit.jupiter.api.Test;

/**
 * The rule engine's gRPC stubs load on the protobuf-java this application ships with.
 *
 * <p>Stubs generated by a newer protoc than the runtime refuse to load ("Detected incompatible
 * Protobuf Gencode/Runtime versions"), and since the gRPC server registers them at startup, the
 * whole application then fails to start — which is what the 2.26.0 and 2.27.0 images did with gRPC
 * on, after the protoc in rule-runtime was bumped past the protobuf-java Spring Boot manages. No
 * test started the server, so nothing noticed. This one runs on the application's own classpath.
 */
class RuleGrpcStubsLoadTest {

    @Test
    void the_generated_stubs_load_on_the_shipped_protobuf_runtime() {
        assertThatCode(GetRuleRequest::getDefaultInstance).doesNotThrowAnyException();
    }
}
